"""Self-contained, escaped HTML reports with shared print-safe letterhead."""
import base64,html,datetime
from pathlib import Path
from document_report import E,content,TITLES,qty_fmt
ROOT=Path(__file__).parent

def data(path,mime):return 'data:'+mime+';base64,'+base64.b64encode((ROOT/path).read_bytes()).decode()
def header():
 return '<header class="company"><div class="company-left"><svg class="wordmark" viewBox="42 215 2087 286" xmlns="http://www.w3.org/2000/svg"><image width="2170" height="725" href="'+data('assets/report-biomed-sharp.png','image/png')+'"/></svg><strong>บริษัท ไบโอเมด ไดแอกนอสติกส์ (ประเทศไทย) จำกัด</strong><span>Biomed Diagnostics (Thailand) Co., Ltd.</span><span>1518/4 อาคารเก่งรุ่งเรืองชัย ชั้น 7 ถ.ประชาราษฎร์ 1 แขวงวงศ์สว่าง เขตบางซื่อ กรุงเทพฯ 10800</span><span>1518/4 Kengrungruengchai Bldg., 7th Fl., Pracharaj Sai 1 Rd., Wongsawang, Bangsue, Bangkok 10800</span></div><svg class="iso" viewBox="195 158 861 980" xmlns="http://www.w3.org/2000/svg"><image width="1254" height="1254" href="'+data('assets/report-masci-iso13485.png','image/png')+'"/></svg><div class="contact">Tel: +66 2 5870256-58 · Fax: +66 2 5870255 · Taxpayer ID: 012546003765<br>Email: sales@biomedthai.com · Website: www.biomedthai.com</div></header>'
def shell(title,reference,body,form=False):
 css='''@font-face{font-family:Sarabun;src:url(FONT)}*{box-sizing:border-box}body{margin:0;background:#edf3f6;color:#193b4d;font:10pt/1.4 Sarabun,Arial,sans-serif}.sheet{max-width:210mm;margin:20px auto;background:white;padding:10mm;box-shadow:0 2px 14px #1235}.company{display:grid;grid-template-columns:minmax(0,1fr) 26mm;gap:3mm 5mm;margin-bottom:6mm}.company-left{display:grid;align-content:start;gap:1mm;font-size:7pt;line-height:1.25}.company-left strong{font-size:9pt}.wordmark{display:block;width:83mm;max-width:100%;height:12mm;margin-bottom:2mm}.iso{width:26mm;height:29mm}.contact{grid-column:1/-1;border-top:1px solid #264e64;padding-top:2mm;font-size:7.5pt}.toolbar{max-width:210mm;margin:16px auto;display:flex;justify-content:flex-end;gap:10px;padding:0 12px}.toolbar button{padding:10px 18px;border:1px solid #9bbccc;border-radius:7px;background:white;color:#16465e;font:14px Arial;cursor:pointer}h1{font-size:19pt;margin:0 0 6pt}h2{font-size:11pt;margin:14pt 0 5pt}h3{font-size:9pt;margin:0 0 5pt}p{margin:5pt 0}table{border-collapse:collapse;width:100%;font-size:8.5pt}th,td{text-align:left;vertical-align:top;padding:5pt;border-bottom:1px solid #d9e5eb;overflow-wrap:anywhere}th{background:#edf5f8}thead{display:table-header-group}tr{break-inside:avoid}.num{text-align:right}.meta td{width:50%}.label,.note{color:#607c8d;font-size:8pt}.totals{width:50%;margin-left:50%;break-inside:avoid}.grand{font-weight:bold;background:#edf5f8}.form-meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));font-size:8pt}.form-meta>div{padding:4pt 5pt;border:1px solid #d4e2ea;overflow-wrap:anywhere}.form-section{border:1px solid #d4e2ea;margin-top:7pt;break-inside:avoid}.form-section h2{font-size:9pt;background:#edf5f8;padding:4pt 6pt;margin:0}.form-section p{padding:4pt 6pt;font-size:8.5pt;min-height:28pt;white-space:pre-wrap;overflow-wrap:anywhere}.feedback{table-layout:fixed;font-size:7.5pt}.feedback td{overflow-wrap:anywhere}.signatures{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10pt;margin-top:10pt;break-inside:avoid}.signatures>div{border:1px solid #b9d1de;padding:7pt;min-height:90pt;font-size:8pt;overflow-wrap:anywhere}.signature{display:block;width:100%;height:54pt;margin:2pt 0}.report-foot{margin-top:10pt;border-top:1px solid #d6e4ec;padding-top:4pt;font-size:7pt;color:#627d8e}.service-form{line-height:1.25}.service-form h1{font-size:17pt}.service-form .company{margin-bottom:4mm}@page{size:A4;margin:54mm 10mm 13mm}@media print{body{background:white}.sheet{padding:0;margin:0;max-width:none;box-shadow:none}.toolbar{display:none}.company{position:fixed;top:-44mm;left:0;right:0;height:42mm;margin:0}.report-foot{position:fixed;bottom:-9mm;left:0;right:0;margin:0}.signatures{min-height:0}}@media screen and (max-width:650px){.sheet{padding:16px;margin:0}.company-left{font-size:6.5pt}.company{grid-template-columns:minmax(0,1fr) 22mm}.iso{width:22mm;height:26mm}.meta,.meta tbody,.meta tr,.meta td{display:block;width:100%}.form-meta,.signatures{grid-template-columns:minmax(0,1fr)}.totals{width:100%;margin-left:0}.table-scroll{overflow:auto}.table-scroll table{min-width:600px}}'''.replace('FONT',data('reference/service-report/Sarabun-Regular.ttf','font/ttf'))
 return '<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; font-src data:; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><title>'+E(title)+' · '+E(reference)+'</title><style>'+css+'</style></head><body><nav class="toolbar"><button type="button" onclick="document.fonts.ready.then(function(){window.print()})">Print report</button></nav><article class="sheet '+('service-form' if form else '')+'">'+header()+'<main>'+body+'</main><footer class="report-foot">'+E(title)+' · '+E(reference)+' · Biomed Diagnostics (Thailand) Co., Ltd.'+(' · FM-FSE-01, Rev. 01 · Effective date: 18 AUG 2025' if title=='Service Report' else '')+'</footer></article></body></html>'
def document(d,state):return shell(TITLES.get(d['kind'],d['kind']),d.get('ref',''),content(d,state))
def service(data):
 body='<h1>'+E(data['title'])+'</h1><p class="note">'+E(data.get('reference'))+' · '+E(data.get('status'))+'</p><div class="form-meta">'+''.join('<div><b>'+E(k)+':</b> '+E(v or '—')+'</div>' for k,v in data.get('meta',[]))+'</div>'
 for label,text in [(data.get('issueLabel','Problem / diagnosis'),data.get('issue')),(data.get('actionLabel','Solution / action taken'),data.get('action')),('Result / follow-up',data.get('result'))]:body+='<section class="form-section"><h2>'+E(label)+'</h2><p>'+E(text or '—')+'</p></section>'
 parts=data.get('parts',[]);text='\n'.join(str(p.get('catalogueNo') or '')+' · '+str(p.get('name') or '')+' · Qty '+qty_fmt(p.get('qty',0)) for p in parts) if parts else data.get('products') or 'No parts recorded.'
 body+='<section class="form-section"><h2>'+E(data.get('partsLabel','Parts used'))+'</h2><p>'+E(text)+'</p></section><section class="form-section"><h2>Customer feedback</h2><table class="feedback"><tr>'
 keys=[('feedbackSolved','Issue resolved'),('feedbackSpeed','Speed'),('feedbackPreparedness','Preparedness'),('feedbackCourtesy','Courtesy'),('feedbackSatisfaction','Satisfaction')];feedback=data.get('feedback',{})
 body+=''.join('<th>'+E(label)+'</th>' for k,label in keys)+'</tr><tr>'+''.join('<td>'+E(feedback.get(k) or 'Not rated')+'</td>' for k,label in keys)+'</tr></table><p>Comments: '+E(feedback.get('feedbackComment') or '—')+'</p></section>'
 body+='<section class="signatures"><div><h3>'+E(data.get('personLabel','Service engineer'))+' - printed name</h3><p>'+E(data.get('person') or 'Not assigned')+'</p><p>Date: '+E(data.get('date') or '—')+'</p></div><div><h3>Customer acknowledgement</h3>'
 sig=data.get('signature')
 if sig:
  stamp=sig.get('signedAt','')
  try:stamp=datetime.datetime.fromisoformat(stamp).astimezone(datetime.timezone(datetime.timedelta(hours=7))).strftime('%d/%m/%Y %H:%M')
  except (ValueError,TypeError):pass
  body+='<svg class="signature" viewBox="0 0 600 180" role="img" aria-label="Saved customer signature">'+''.join('<polyline fill="none" stroke="#12394f" stroke-width="2" points="'+' '.join(str(float(x)*600)+','+str(float(y)*180) for x,y in stroke)+'"/>' for stroke in sig.get('strokes',[]))+'</svg><p>'+E(sig.get('name'))+'</p><p>Signed: '+E(stamp)+'</p>'
 else:body+='<p>Customer signature not provided</p>'
 body+='</div></section>'
 return shell(data['title'],data.get('reference',''),body,True)
